// Regenerates src/vendor/*.generated.mjs from the pinned rrweb / rrweb-player
// npm packages (MIT, rrweb-io/rrweb). Run `npm run vendor:rrweb` after
// bumping the versions in package.json. The Worker never reads node_modules
// at runtime; these generated files are the only thing it imports, so they
// are committed.
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "src", "vendor");
const MODULES = join(ROOT, "node_modules");

function pkgDir(name) {
  return join(MODULES, name);
}

function pkgVersion(name) {
  return JSON.parse(readFileSync(join(pkgDir(name), "package.json"), "utf8")).version;
}

function readDist(name, file) {
  return readFileSync(join(pkgDir(name), "dist", file), "utf8");
}

function writeGenerated(file, { source, comment, exportName, content }) {
  const banner = `// GENERATED by scripts/vendor-rrweb.mjs from ${source} — do not hand-edit.\n// ${comment}\nexport const ${exportName} = ${JSON.stringify(content)};\n`;
  writeFileSync(join(OUT, file), banner);
  console.log(`wrote ${file} (${content.length} bytes)`);
}

const rrwebVersion = pkgVersion("rrweb");
const playerVersion = pkgVersion("rrweb-player");

writeGenerated("rrweb-recorder.generated.mjs", {
  source: `rrweb@${rrwebVersion} dist/rrweb.umd.min.cjs`,
  comment: "MIT, Copyright (c) rrweb-io/rrweb contributors. Exposes window.rrweb.record().",
  exportName: "RRWEB_RECORDER_JS",
  content: readDist("rrweb", "rrweb.umd.min.cjs"),
});

writeGenerated("rrweb-player.generated.mjs", {
  source: `rrweb-player@${playerVersion} dist/rrweb-player.umd.min.cjs`,
  comment: "MIT, Copyright (c) rrweb-io/rrweb contributors. Exposes window.rrwebPlayer.",
  exportName: "RRWEB_PLAYER_JS",
  content: readDist("rrweb-player", "rrweb-player.umd.min.cjs"),
});

writeGenerated("rrweb-player.generated.css.mjs", {
  source: `rrweb-player@${playerVersion} dist/style.min.css`,
  comment: "MIT, Copyright (c) rrweb-io/rrweb contributors.",
  exportName: "RRWEB_PLAYER_CSS",
  content: readDist("rrweb-player", "style.min.css"),
});

writeFileSync(
  join(OUT, "VERSIONS.json"),
  JSON.stringify({ rrweb: rrwebVersion, "rrweb-player": playerVersion, generated_at: new Date().toISOString() }, null, 2) + "\n",
);
